import{_ as a,o as n,c as l,a0 as e}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"firewall","description":"","frontmatter":{},"headers":[],"relativePath":"linux/firewall.md","filePath":"linux/firewall.md","lastUpdated":1791039142000}'),p={name:"linux/firewall.md"};function o(r,s,c,i,t,d){return n(),l("div",null,[...s[0]||(s[0]=[e(`<h1 id="firewall" tabindex="-1">firewall <a class="header-anchor" href="#firewall" aria-label="Permalink to &quot;firewall&quot;">​</a></h1><p>常见于linux系统下的应用层防火墙工具，iptables升级版。FirewallD 使用服务（service） 和区域（zone）来代替 iptables 的规则（rule）和链（chain）</p><h2 id="管理" tabindex="-1">管理 <a class="header-anchor" href="#管理" aria-label="Permalink to &quot;管理&quot;">​</a></h2><h4 id="_1-启动服务-并在系统引导时启动该服务" tabindex="-1">1 启动服务，并在系统引导时启动该服务： <a class="header-anchor" href="#_1-启动服务-并在系统引导时启动该服务" aria-label="Permalink to &quot;1 启动服务，并在系统引导时启动该服务：&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">sudo systemctl start firewalld</span></span>
<span class="line"><span style="color:#24292E;">sudo systemctl enable firewalld</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>要停止并禁用：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">sudo systemctl stop firewalld</span></span>
<span class="line"><span style="color:#24292E;">sudo systemctl disable firewalld</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="_2-检查防火墙状态。输出应该是-running-或者-not-running。" tabindex="-1">2 检查防火墙状态。输出应该是 running 或者 not running。 <a class="header-anchor" href="#_2-检查防火墙状态。输出应该是-running-或者-not-running。" aria-label="Permalink to &quot;2 检查防火墙状态。输出应该是 running 或者 not running。&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">sudo firewall</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">cmd </span><span style="color:#D73A49;">--</span><span style="color:#24292E;">state</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_3-要查看-firewalld-守护进程的状态" tabindex="-1">3 要查看 FirewallD 守护进程的状态： <a class="header-anchor" href="#_3-要查看-firewalld-守护进程的状态" aria-label="Permalink to &quot;3 要查看 FirewallD 守护进程的状态：&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">sudo systemctl status firewalld</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_4-重新加载-firewalld-配置" tabindex="-1">4 重新加载 FirewallD 配置： <a class="header-anchor" href="#_4-重新加载-firewalld-配置" aria-label="Permalink to &quot;4 重新加载 FirewallD 配置：&quot;">​</a></h4><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">sudo firewall</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">cmd </span><span style="color:#D73A49;">--</span><span style="color:#24292E;">reload</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="区域" tabindex="-1">区域 <a class="header-anchor" href="#区域" aria-label="Permalink to &quot;区域&quot;">​</a></h2><p>“区域”是针对给定位置或场景（例如家庭、公共、受信任等）可能具有的各种信任级别的预构建规则集。不同的区域允许不同的网络服 务和入站流量类型，而拒绝其他任何流量。 首次启用 FirewallD 后，public 将是默认区域</p><p>默认情况下，有以下的区域（zone）可用：</p><ul><li><code>drop</code> 丢弃所有传入的网络数据包并且无回应，只有传出网络连接可用</li><li><code>block</code> 拒绝所有传入网络数据包并回应一条主机禁止的 ICMP 消息，只有传出网络连接可用</li><li><code>public</code> 只接受被选择的传入网络连接，用于公共区域</li><li><code>external</code> 用于启用了地址伪装的外部网络，只接受选定的传入网络连接</li><li><code>dmz</code> DMZ 隔离区，外部受限地访问内部网络，只接受选定的传入网络连接</li><li><code>work</code> 对于处在你工作区域内的计算机，只接受被选择的传入网络连接</li><li><code>home</code> 对于处在你家庭区域内的计算机，只接受被选择的传入网络连接</li><li><code>internal</code> 对于处在你内部网络的计算机，只接受被选择的传入网络连接</li><li><code>trusted</code> 所有网络连接都接受</li></ul><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">sudo firewall</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">cmd </span><span style="color:#D73A49;">--</span><span style="color:#24292E;">get</span><span style="color:#D73A49;">-default-</span><span style="color:#24292E;">zone                </span><span style="color:#6A737D;">//找到默认区域</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">sudo firewall</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">cmd </span><span style="color:#D73A49;">--</span><span style="color:#24292E;">set</span><span style="color:#D73A49;">-default-</span><span style="color:#24292E;">zone</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">internal       </span><span style="color:#6A737D;">//修改默认区域</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">sudo firewall</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">cmd </span><span style="color:#D73A49;">--</span><span style="color:#24292E;">get</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">active</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">zones                </span><span style="color:#6A737D;">//查看你网络接口使用的区域</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">//输出</span></span>
<span class="line"><span style="color:#24292E;">public</span></span>
<span class="line"><span style="color:#6F42C1;">  interfaces</span><span style="color:#24292E;">: eth0</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">sudo firewall</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">cmd </span><span style="color:#D73A49;">--</span><span style="color:#24292E;">zone</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">public </span><span style="color:#D73A49;">--</span><span style="color:#24292E;">list</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">all          </span><span style="color:#6A737D;">//得到特定区域的所有配置</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">//输出</span></span>
<span class="line"><span style="color:#6F42C1;">public</span><span style="color:#24292E;"> (default, active)</span></span>
<span class="line"><span style="color:#6F42C1;">  interfaces</span><span style="color:#24292E;">: ens160</span></span>
<span class="line"><span style="color:#6F42C1;">  sources</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#6F42C1;">  services</span><span style="color:#24292E;">: dhcpv6</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">client http ssh</span></span>
<span class="line"><span style="color:#6F42C1;">  ports</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">12345</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">tcp</span></span>
<span class="line"><span style="color:#6F42C1;">  masquerade</span><span style="color:#24292E;">: no</span></span>
<span class="line"><span style="color:#24292E;">  forward</span><span style="color:#D73A49;">-</span><span style="color:#6F42C1;">ports</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#24292E;">  icmp</span><span style="color:#D73A49;">-</span><span style="color:#6F42C1;">blocks</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#24292E;">  rich </span><span style="color:#6F42C1;">rules</span><span style="color:#24292E;">:</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">sudo firewall</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">cmd </span><span style="color:#D73A49;">--</span><span style="color:#24292E;">list</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">all</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">zones                  </span><span style="color:#6A737D;">//得到所有区域的配置</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br></div></div><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>FirewallD 使用 XML 进行配置。除非是非常特殊的配置，你不必处理它们，而应该使用 firewall-cmd</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>firewalld 的操作只有重启之后才有效：service firewalld restart 重启</p></div><h3 id="系统配置目录" tabindex="-1">系统配置目录 <a class="header-anchor" href="#系统配置目录" aria-label="Permalink to &quot;系统配置目录&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">/</span><span style="color:#24292E;">usr</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">lib</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">firewalld</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">services</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>目录中存放定义好的网络服务和端口参数，系统参数，不能修改</p><h3 id="用户配置目录" tabindex="-1">用户配置目录 <a class="header-anchor" href="#用户配置目录" aria-label="Permalink to &quot;用户配置目录&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">/</span><span style="color:#24292E;">etc</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">firewalld</span><span style="color:#D73A49;">/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="配置集" tabindex="-1">配置集 <a class="header-anchor" href="#配置集" aria-label="Permalink to &quot;配置集&quot;">​</a></h3><p>FirewallD 使用两个配置集：“运行时”和“持久”。 在系统重新启动或重新启动 FirewallD 时，不会保留运行时的配置更改，而对持 久配置集的更改不会应用于正在运行的系统。</p><p>默认情况下，firewall-cmd 命令适用于运行时配置，但使用 --permanent 标志将保存到持久配置中</p>`,29)])])}const y=a(p,[["render",o]]);export{b as __pageData,y as default};
